import{f as a,J as r,o as t,c as n,a6 as o,b as i,w as s,a as c,K as l,a7 as h}from"./chunks/framework.Dd1qhYRL.js";const E=JSON.parse('{"title":"SQL Terminal","description":"","frontmatter":{},"headers":[],"relativePath":"guide/database/terminal.md","filePath":"guide/database/terminal.md"}'),p={name:"guide/database/terminal.md"};function u(g,e,y,m,b,f){const d=r("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o(`<h1 id="sql-terminal" tabindex="-1">SQL Terminal <a class="header-anchor" href="#sql-terminal" aria-label="Permalink to “SQL Terminal”">​</a></h1><p>Run SQL against a config&#39;s database from the shell or the TUI, with every statement checked against the config&#39;s role first.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> query</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;SELECT party_id, order_no, status FROM sales_order ORDER BY 1, 2&quot;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Columns: party_id, order_no, status</span></span>
<span class="line"><span>{&quot;party_id&quot;:1,&quot;order_no&quot;:1,&quot;status&quot;:&quot;paid&quot;}</span></span>
<span class="line"><span>{&quot;party_id&quot;:2,&quot;order_no&quot;:1,&quot;status&quot;:&quot;invoiced&quot;}</span></span>
<span class="line"><span>{&quot;party_id&quot;:2,&quot;order_no&quot;:2,&quot;status&quot;:&quot;open&quot;}</span></span>
<span class="line"><span>3 rows returned (2ms)</span></span></code></pre></div><p><code>Shift+Q</code> on any TUI screen opens the active config in an interactive terminal with a results grid and saved history. From a shell, run <code>noorm sql repl --config dev</code>, which needs a TTY and exits with a usage error under <code>--yes</code> or <code>NOORM_YES</code>. <a href="/cli/sql.html"><code>noorm sql</code></a> covers <code>query</code>, including <code>-f file.sql</code> and <code>--json</code>.</p><h2 id="what-am-i-allowed-to-run" tabindex="-1">What am I allowed to run? <a class="header-anchor" href="#what-am-i-allowed-to-run" aria-label="Permalink to “What am I allowed to run?”">​</a></h2><p>The text is parsed and classified before anything reaches the database. The highest class wins:</p>`,7)),(t(),i(h,null,{default:s(()=>[l(d,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Q%5B%22SQL%20text%22%5D%20--%3E%20P%7B%22parses%3F%22%7D%0A%20%20%20%20P%20--%3E%7Cyes%7C%20T%5B%22class%20of%20every%3Cbr%2F%3Estatement%20in%20the%20tree%22%5D%0A%20%20%20%20P%20--%3E%7Cno%7C%20K%5B%22class%20of%20each%20statement%3Cbr%2F%3Eby%20its%20first%20keyword%22%5D%0A%20%20%20%20T%20--%3E%20H%5B%22highest%20class%20wins%22%5D%0A%20%20%20%20K%20--%3E%20H%0A%20%20%20%20H%20--%3E%20G%7B%22role%20allows%20it%3F%22%7D%0A%20%20%20%20G%20--%3E%7Cno%7C%20X%5B%22refused%2C%20nothing%20sent%22%5D%0A%20%20%20%20G%20--%3E%7Cyes%7C%20DB%5B%22runs%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o(`<table tabindex="0"><thead><tr><th>Class</th><th>Statements</th><th><code>viewer</code></th><th><code>operator</code></th><th><code>admin</code></th></tr></thead><tbody><tr><td><code>sql:read</code></td><td><code>SELECT</code>, <code>VALUES</code>, <code>TABLE</code>, an <code>EXPLAIN</code> of a read, <code>SHOW</code> and <code>DESCRIBE</code> on MySQL</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td><code>sql:write</code></td><td><code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>, <code>MERGE</code></td><td>no</td><td>yes</td><td>yes</td></tr><tr><td><code>sql:ddl</code></td><td>everything else: <code>CREATE</code>, <code>ALTER</code>, <code>DROP</code>, <code>TRUNCATE</code>, <code>GRANT</code>, <code>SET</code>, <code>CALL</code>, <code>EXEC</code>, and input no keyword matches</td><td>no</td><td>no</td><td>yes</td></tr></tbody></table><p><code>src/core/policy/classify.ts</code> decides these cases:</p><table tabindex="0"><thead><tr><th>Input (PostgreSQL)</th><th>Class</th><th>Why</th></tr></thead><tbody><tr><td><code>WITH gone AS (DELETE FROM order_line RETURNING *) SELECT * FROM gone</code></td><td><code>sql:write</code></td><td>a <code>DELETE</code> inside the <code>WITH</code></td></tr><tr><td><code>EXPLAIN ANALYZE DELETE FROM order_line</code></td><td><code>sql:write</code></td><td><code>EXPLAIN</code> takes the class of what it runs</td></tr><tr><td><code>SELECT * INTO order_copy FROM sales_order</code></td><td><code>sql:ddl</code></td><td>it creates a table</td></tr><tr><td><code>SELECT pg_terminate_backend(pid) FROM pg_stat_activity</code></td><td><code>sql:write</code></td><td>a side-effecting builtin on the denylist</td></tr></tbody></table><p>The denylist names known-dangerous builtins, such as <code>nextval</code> and <code>pg_read_file</code>. It stops accidental writes on a <code>viewer</code> config and is not a sandbox.</p><h2 id="how-do-i-work-in-the-terminal" tabindex="-1">How do I work in the terminal? <a class="header-anchor" href="#how-do-i-work-in-the-terminal" aria-label="Permalink to “How do I work in the terminal?”">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>Keys</th></tr></thead><tbody><tr><td>Query input</td><td><code>Enter</code> runs, <code>Shift+Enter</code> adds a line. <code>Shift+Tab</code> toggles edit mode (<code>[EDIT]&gt;</code>), where <code>Enter</code> adds a line. <code>Tab</code> inserts four spaces. <code>↑</code> <code>↓</code> recall earlier queries and <code>h</code> opens history, both on an empty input</td></tr><tr><td>Results grid</td><td><code>↑</code> <code>↓</code> move. <code>Enter</code> opens the row as YAML or JSON (<code>←</code> <code>→</code> change row, <code>f</code> switches format). <code>/</code> filters, <code>s</code> sorts, <code>c</code> clears both</td></tr><tr><td>Between them</td><td>A query that returns rows opens the grid. <code>Tab</code> or <code>Esc</code> returns to the query</td></tr><tr><td>Any time</td><td><code>Esc</code> stops a running query or connect, otherwise clears the input, and on an empty input leaves</td></tr></tbody></table><p>A statement without rows shows <code>✓ 1 row(s) affected (5ms)</code> or <code>✓ Query executed (42ms)</code>. A failure shows <code>✗</code> and the server&#39;s message.</p><h2 id="how-do-i-stop-a-query" tabindex="-1">How do I stop a query? <a class="header-anchor" href="#how-do-i-stop-a-query" aria-label="Permalink to “How do I stop a query?”">​</a></h2><p><code>Esc</code> returns the terminal to you. Whether the server stops working depends on the dialect:</p><table tabindex="0"><thead><tr><th>Dialect</th><th>On <code>Esc</code></th></tr></thead><tbody><tr><td>PostgreSQL</td><td><code>pg_cancel_backend</code> on a second connection</td></tr><tr><td>MySQL</td><td><code>KILL QUERY</code> on a second connection</td></tr><tr><td>SQL Server</td><td>nothing reaches the server</td></tr><tr><td>SQLite</td><td>nothing reaches the server</td></tr></tbody></table><p>The first two show <code>Cancelled. The server was asked to stop the query.</code> The last two show <code>Stopped waiting. The query may still be running on the server.</code> There the query may keep running and holding its locks, so kill it server-side if that matters.</p><h2 id="where-does-history-go" tabindex="-1">Where does history go? <a class="header-anchor" href="#where-does-history-go" aria-label="Permalink to “Where does history go?”">​</a></h2><p>Only the interactive terminal records history, one file set per config. <code>sql query</code> records nothing. A statement the role refused is recorded as a failure.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> history</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SQL history for &#39;dev&#39; (2 entries):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ✓  Oct 21 at 01:42:51  5ms · 1 row(s)</span></span>
<span class="line"><span>     UPDATE sales_order SET status = &#39;paid&#39; WHERE party_id = 2 AND order_no = 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ✗  Oct 21 at 01:42:51  2ms · relation &quot;sale_order&quot; does not exist</span></span>
<span class="line"><span>     SELECT * FROM sale_order</span></span></code></pre></div><p>In the TUI, <code>h</code> opens the same list. <code>r</code> sends the selected query back to the input, <code>Enter</code> opens its stored rows or error, and <code>c</code> opens the clear menu. From a shell: <code>noorm sql clear --older-than 3 --yes</code>.</p><div class="warning custom-block"><p class="custom-block-title">History is not encrypted</p><p>Query text sits in <code>.noorm/state/history/&lt;config&gt;.json</code> and returned rows sit gzipped in <code>.noorm/state/history/&lt;config&gt;/</code>. Both are owner-only (<code>0600</code>, in a <code>0700</code> directory), but anything a <code>SELECT</code> pulled from a credentials or PII table is readable by your user account. Clear the history after a sensitive query.</p></div><h2 id="what-bites" tabindex="-1">What bites <a class="header-anchor" href="#what-bites" aria-label="Permalink to “What bites”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>&quot;sql:write&quot; is not allowed on config &quot;ro&quot; (role: viewer).</code></td><td>The class needs a higher role than your channel has. In an agent session the channel is <code>agent</code>, which defaults to <code>viewer</code></td><td>Raise the role, or see <a href="/guide/environments/configs.html#which-channel-is-a-process-on">channels</a></td></tr><tr><td><code>SHOW search_path</code> (PostgreSQL) or <code>PRAGMA …</code> (SQLite) is refused below <code>admin</code></td><td>Both parse as statements the classifier does not list as reads, so they count as <code>sql:ddl</code></td><td><code>SELECT current_setting(&#39;search_path&#39;)</code>, or <code>SELECT * FROM pragma_table_info(&#39;sales_order&#39;)</code></td></tr><tr><td><code>noorm sql -f reports/monthly.sql</code> prints <code>Unknown command</code></td><td>The bare form needs the SQL as the first token after <code>sql</code></td><td><code>noorm sql query -f reports/monthly.sql</code></td></tr><tr><td><code>noorm sql history</code> is empty after you ran queries</td><td>They ran through <code>sql query</code></td><td>Run them in the terminal</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/database/explore.html">Schema Explorer</a>: read the structure before you query it</li><li><a href="/guide/environments/configs.html">Configs</a>: roles and channels</li><li><a href="/cli/sql.html"><code>noorm sql</code></a>: flags for <code>query</code>, <code>history</code>, and <code>clear</code></li><li><a href="/guide/sql-files/execution.html">Run files</a>: run SQL files with change detection</li></ul>`,21))])}const q=a(p,[["render",u]]);export{E as __pageData,q as default};
